variables['ab814f74-75bb-4643-a513-9816d65fc3bc'] = [];
variables['6a3c25f9-5eda-4390-a410-a8f0c767b7d7'] = false;

try {
  // Check if user is authenticated
  const isAuthenticated = pluginVariables['1fa0dd68-5069-436c-9a7d-3b54c340f1fa']['isAuthenticated'];
  const user = pluginVariables['1fa0dd68-5069-436c-9a7d-3b54c340f1fa']['user'];

  // Fetch pins data from Supabase
  const pinsCollection = await utilsFunctions.fetchCollection('f9ef41c3-1c53-4857-855b-f2f6a40b7186');
  if (pinsCollection && pinsCollection.data) {
    variables['ab814f74-75bb-4643-a513-9816d65fc3bc'] = pinsCollection.data;
    console.log('Pins loaded:', pinsCollection.data.length, 'pins');
  }

  // Check admin role if user is authenticated
  if (isAuthenticated && user && user.id) {
    try {
      // Get user profile to check role_id
      const userProfileCollection = await utilsFunctions.fetchCollection('user-profiles');
      if (userProfileCollection && userProfileCollection.data) {
        const userProfile = userProfileCollection.data.find(profile => profile.user_id === user.id);

        if (userProfile && userProfile.role_id) {
          // Fetch roles to check if user has admin role
          const rolesCollection = await utilsFunctions.fetchCollection('roles');
          if (rolesCollection && rolesCollection.data) {
            const adminRole = rolesCollection.data.find(role => 
              role.id === userProfile.role_id && role.name === 'admin'
            );

            if (adminRole) {
              variables['6a3c25f9-5eda-4390-a410-a8f0c767b7d7'] = true;
              console.log('User has admin role');
            }
          }
        }
      }
    } catch (roleError) {
      console.log('Could not check admin role:', roleError.message);
    }
  }

} catch (error) {
  console.error('Error loading map data:', error);
}

