// Initialize isAdmin to false
variables['6a3c25f9-5eda-4390-a410-a8f0c767b7d7'] = false;

try {
  // Check if user is authenticated
  const isAuthenticated = pluginVariables['1fa0dd68-5069-436c-9a7d-3b54c340f1fa']['isAuthenticated'];
  const user = pluginVariables['1fa0dd68-5069-436c-9a7d-3b54c340f1fa']['user'];

  if (!isAuthenticated || !user || !user.id) {
    console.log('User not authenticated, skipping admin check');
    return;
  }

  // Query users table to get user's role_id
  const userResult = await utilsFunctions.executePluginFunction('f9ef41c3-1c53-4857-855b-f2f6a40b7186', 'select', {
    table: 'users',
    fieldsMode: 'guided',
    dataFields: ['id', 'role_id'],
    filters: [
      {
        fn: 'eq',
        column: 'id',
        value: user.id,
        isEnabled: true
      }
    ]
  });

  if (!userResult || !userResult.length || !userResult[0].role_id) {
    console.log('User not found or no role assigned');
    return;
  }

  // Query roles table to check if role is admin
  const roleResult = await utilsFunctions.executePluginFunction('f9ef41c3-1c53-4857-855b-f2f6a40b7186', 'select', {
    table: 'roles',
    fieldsMode: 'guided',
    dataFields: ['id', 'name'],
    filters: [
      {
        fn: 'eq',
        column: 'id',
        value: userResult[0].role_id,
        isEnabled: true
      }
    ]
  });

  if (roleResult && roleResult.length && roleResult[0].name === 'admin') {
    variables['6a3c25f9-5eda-4390-a410-a8f0c767b7d7'] = true;
    console.log('User has admin role');
  }

} catch (error) {
  console.error('Error checking admin role:', error);
}

