  const hash = wwLib.getFrontWindow().location.hash;

  if (hash && hash.includes('access_token')) {
    console.log('OAuth callback detected, fetching user data');

    // Fetch user data using Supabase Auth
    await utilsFunctions.executePluginFunction('1fa0dd68-5069-436c-9a7d-3b54c340f1fa', 'fetchUser', {});

    // Clean up URL hash
    wwLib.getFrontWindow().history.replaceState(null, null, wwLib.getFrontWindow().location.pathname);

    console.log('OAuth callback processed successfully');
  }
} catch (error) {
  console.error('Error handling OAuth callback:', error);
}

